// Read payload
const data = msg.payload;

// Validation checks
if (data.serialId === undefined) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: "serialId is required"
    };
    return [null, msg];
}

if (!Array.isArray(data.Panels)) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: "Panels must be an array"
    };
    return [null, msg];
}

if (data.PanelCount !== data.Panels.length) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: "PanelCount does not match Panels length"
    };
    return [null, msg];
}

if (data.stationId === undefined) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: "Station id must be there"
    };
    return [null, msg];
}

if (data.paramValue === undefined) {
    msg.statusCode = 400;
    msg.payload = {
        success: false,
        message: "Param value must be there"
    };
    return [null, msg];
}

// Validation successful
return [msg, null];

const input = msg.payload;

let workItems = [];

for(let panel of input.Panels){

    workItems.push({

        serialId: input.serialId,

        station: input.stationId,

        panel: panel,

        paramValue: input.paramValue

    });

}

msg.payload = workItems;

return msg;

const stationConfigs = global.get("stationConfigs");
const station = msg.payload.station;
const stationConfig = stationConfigs[station];

// const determiningParameter = stationConfig.determiningParameter;

const determiningValue = msg.payload.paramValue;

let selectedRule = null;

for(const rule of stationConfig.rules){

    if(determiningValue >= rule.min &&
       determiningValue < rule.max){

        selectedRule = rule;

        break;

    }

}

if(selectedRule == null){

    node.error(`No matching rule for station=${station}, value=${determiningValue}`);

    return null;

}

msg.rule = selectedRule;

return msg;

function randomBetween(min, max) {
    return +(Math.random() * (max - min) + min).toFixed(3);
}

function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function randomBit() {
    return Math.floor(Math.random() * 2);
}

function calculate(def) {

    switch (def.type) {

        case "randomFloat":
            return randomBetween(def.min, def.max);

        case "randomInt":
            return randomInt(def.min, def.max);

        case "randomBit":
            return randomBit();

        case "constant":
            return def.value;

        default:
            return null;
    }

}

const calculated = {};

// msg.rule.parameters is now an object, not an array
for (const [parameter, definition] of Object.entries(msg.rule.parameters)) {

    calculated[parameter] = calculate(definition);
}

msg.parameters = calculated;

return msg;

const result = {};

result.serialId = msg.payload.serialId;

result.stationId = msg.payload.station;

result[msg.payload.panel] = msg.parameters;

msg.payload = result;

return msg;

const stationConfigs = {
    "deburring": {

        // determiningParameter: "thickness",
        rules: [
            {
                min:1.6,
                max:2,

                parameters:{

                    conveyorSpeed:{
                        type:"randomFloat",
                        min:1.2,
                        max:1.8
                    },

                    brushPenetrationDepth:{
                        type:"randomInt",
                        min:0.03,
                        max:0.05
                    },

                    waterBlastPressure:{
                        type:"randomFloat",
                        min:1.5,
                        max:2
                    },

                    dryerTemperature:{
                        type:"randomFloat",
                        min:20,
                        max:25
                    },

                    waterLevel:{
                        type:"randomBit"
                    }

                }

            },

            {
                min:2.4,
                max:3,

                parameters:{

                    conveyorSpeed:{
                        type:"randomFloat",
                        min:1.0,
                        max:1.4
                    },

                    brushPenetrationDepth:{
                        type:"randomInt",
                        min:0.04,
                        max:0.06
                    },

                    waterBlastPressure:{
                        type:"randomFloat",
                        min:2.0,
                        max:2.5
                    },

                    dryerTemperature:{
                        type:"randomFloat",
                        min:20,
                        max:25
                    },

                    waterLevel:{
                        type:"randomBit"
                    }

                }

            }

        ]
    }
}

global.set("stationConfigs", stationConfigs);

node.status({
    fill: "green",
    shape: "dot",
    text: "Rules Loaded"
});

return null;
